"""One reusable analytic frame field for all Bundle boundary queries."""
import bpy

from .path_surface_nodes import _Nodes
from . import path_station_nodes

NAME = 'Prochitecture Streets / Bundle analytic frame v1'


def build():
    existing = bpy.data.node_groups.get(NAME)
    if existing:
        if existing.get('revision') != 1:
            raise ValueError('Unexpected Bundle analytic frame revision')
        return existing
    tree = bpy.data.node_groups.new(NAME, 'GeometryNodeTree')
    for name, direction, kind in (
        ('Curves', 'INPUT', 'NodeSocketGeometry'),
        ('Path', 'INPUT', 'NodeSocketInt'),
        ('Parameter', 'INPUT', 'NodeSocketFloat'),
        ('Center', 'OUTPUT', 'NodeSocketVector'),
        ('Lateral', 'OUTPUT', 'NodeSocketVector')):
        tree.interface.new_socket(name=name, in_out=direction, socket_type=kind)
    g = _Nodes(tree)
    inp = g.node('NodeGroupInput', 'Actual paths and common parameter')
    out = g.node('NodeGroupOutput', 'Exact miter or analytic cubic frame')
    center, lateral = path_station_nodes.evaluated_frame(
        g, inp.outputs['Curves'], inp.outputs['Path'], inp.outputs['Parameter'], preserve_knots=True)
    g.set(center, out.inputs['Center'])
    g.set(lateral, out.inputs['Lateral'])
    tree['revision'] = 1
    return tree


def evaluate(g, curves, path, parameter):
    node = g.node('GeometryNodeGroup', 'Shared analytic Bundle boundary frame')
    node.node_tree = build()
    for name, value in (('Curves', curves), ('Path', path), ('Parameter', parameter)):
        g.set(value, node.inputs[name])
    return node.outputs['Center'], node.outputs['Lateral']
